diff --git a/src/core/project.ts b/src/core/project.ts
index 76d1577..6d56602 100644
--- a/src/core/project.ts
+++ b/src/core/project.ts
@@ -6,12 +6,51 @@ export interface Record {
   warns: readonly string[];
 }

+const semanticGroup = (text: string): string | null => {
+  const normalized = text.toLowerCase();
+
+  if (normalized.includes("operational") ||
+      normalized.includes("stateful") ||
+      normalized.includes("always-on") ||
+      normalized.includes("infrastructure that someone has to operate") ||
+      normalized.includes("one more thing to run") ||
+      normalized.includes("managed cache")) {
+    return "no_new_operational_burden";
+  }
+
+  return null;
+};
+
 export const project = (records: readonly Record[]): string => {
+  const seen = new Set<string>();
   const lines: string[] = [];
+
   for (const record of records) {
-    for (const entry of record.ruledOut) lines.push(`- ruled out: ${entry}`);
-    for (const limit of record.limits) lines.push(`- limit: ${limit}`);
-    for (const warn of record.warns) lines.push(`- warn: ${warn}`);
+    for (const entry of record.ruledOut) {
+      const group = semanticGroup(entry);
+      const key = group || entry;
+      if (!seen.has(key)) {
+        seen.add(key);
+        lines.push(`- ruled out: ${entry}`);
+      }
+    }
+
+    for (const limit of record.limits) {
+      const group = semanticGroup(limit);
+      const key = group || limit;
+      if (!seen.has(key)) {
+        seen.add(key);
+        lines.push(`- limit: ${limit}`);
+      }
+    }
+
+    for (const warn of record.warns) {
+      if (!seen.has(warn)) {
+        seen.add(warn);
+        lines.push(`- warn: ${warn}`);
+      }
+    }
   }
+
   return lines.join("\n");
 };
